import { createChart } from '../test/ut/core/utHelper';
import { EChartsType } from '@/src/echarts';

describe('axisLabel_customValues', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        chart.dispose();
    });

    it('formatter receives the index of the rendered label', function () {
        const received: [unknown, number][] = [];
        chart.setOption({
            xAxis: {
                type: 'value',
                min: 0,
                max: 10,
                axisLabel: {
                    customValues: [2, 4, 4, 6, 100],
                    formatter: (value: number, index: number) => {
                        received.push([value, index]);
                        return value + '#' + index;
                    }
                }
            },
            yAxis: {},
            series: [{type: 'line', data: [[0, 1], [10, 2]]}]
        });

        // `100` is out of the extent so it is filtered out. Each remaining item,
        // including the duplicated `4`, keeps its own position.
        expect(received).toEqual([[2, 0], [4, 1], [4, 2], [6, 3]]);
    });

    it('time axis works with customValues and a function formatter', function () {
        const args: number[] = [];
        expect(function () {
            chart.setOption({
                xAxis: {
                    type: 'time',
                    min: +new Date('2024-01-01'),
                    max: +new Date('2024-01-10'),
                    axisLabel: {
                        customValues: [
                            +new Date('2024-01-02'),
                            +new Date('2024-01-05')
                        ],
                        formatter: (value: number, index: number) => {
                            args.push(index);
                            return 'D' + index;
                        }
                    }
                },
                yAxis: {},
                series: [{
                    type: 'line',
                    data: [
                        [+new Date('2024-01-01'), 1],
                        [+new Date('2024-01-10'), 2]
                    ]
                }]
            });
        }).not.toThrow();
        expect(args.length).toBeGreaterThan(0);
    });
});

