import { createChart, getECModel } from '../test/ut/core/utHelper';
import { EChartsType } from '@/src/echarts';
import CartesianAxisModel from '@/src/coord/cartesian/AxisModel';

describe('smallNumber', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        chart.dispose();
    });

    it('interval scale keeps extremely small extent', function () {
        chart.setOption({
            xAxis: {type: 'category', data: ['a', 'b', 'c']},
            yAxis: {type: 'value'},
            series: [{type: 'line', data: [1e-13, 2e-13, 3e-13]}]
        });
        const yAxisModel = getECModel(chart).getComponent('yAxis', 0) as CartesianAxisModel;
        const scale = yAxisModel.axis.scale;
        const extent = scale.getExtent();
        // eslint-disable-next-line no-console
        console.log('extent', extent, 'ticks', scale.getTicks().map(t => t.value));
        expect(extent[1]).toBeGreaterThan(0);
    });

    it('log scale supports big negative exponent', function () {
        chart.setOption({
            xAxis: {type: 'category', data: ['a', 'b', 'c']},
            yAxis: {type: 'log'},
            series: [{type: 'line', data: [1e-15, 1e-13, 1e-11]}]
        });
        const yAxisModel = getECModel(chart).getComponent('yAxis', 0) as CartesianAxisModel;
        const scale = yAxisModel.axis.scale;
        const ticks = scale.getTicks().map(t => t.value);
        // eslint-disable-next-line no-console
        console.log('log extent', scale.getExtent(), 'ticks', ticks);
        ticks.forEach(v => expect(v).toBeGreaterThan(0));
    });
});

