old = """export function increaseInterval(interval: number) {
    const exp10 = Math.pow(10, quantityExponent(interval));
    // Increase interval
    let f = interval / exp10;
    if (!f) {
        f = 1;
    }
    else if (f === 2) {
        f = 3;
    }
    else if (f === 3) {
        f = 5;
    }
    else { // f is 1 or 5
        f *= 2;
    }
    return round(f * exp10);
}"""
new = """export function increaseInterval(interval: number) {
    const exponent = quantityExponent(interval);
    const exp10 = Math.pow(10, exponent);
    // Increase interval
    let f = interval / exp10;
    if (!f) {
        f = 1;
    }
    else if (f === 2) {
        f = 3;
    }
    else if (f === 3) {
        f = 5;
    }
    else { // f is 1 or 5
        f *= 2;
    }
    // The rounding precision has to follow the magnitude of the interval, otherwise
    // an extremely small interval (e.g. `1e-13`) would be rounded to `0`.
    return round(f * exp10, exponent < 0 ? -exponent : 0);
}"""
