34	    const exp10 = Math.pow(10, quantityExponent(Math.abs(val)));
35	    const f = Math.abs(val / exp10);
36	    return f === 0
37	        || f === 1
38	        || f === 2
39	        || f === 3
40	        || f === 5;
41	}
42	
43	export function isIntervalOrLogScale(scale: Scale): scale is LogScale | IntervalScale {
44	    return scale.type === 'interval' || scale.type === 'log';
45	}
46	/**
47	 * @param extent Both extent[0] and extent[1] should be valid number.
48	 *               Should be extent[0] < extent[1].
49	 * @param splitNumber splitNumber should be >= 1.
50	 */
51	export function intervalScaleNiceTicks(
52	    extent: [number, number],
53	    spanWithBreaks: number,
54	    splitNumber: number,
55	    minInterval?: number,
56	    maxInterval?: number
57	): intervalScaleNiceTicksResult {
58	
59	    const result = {} as intervalScaleNiceTicksResult;
60	
61	    let interval = result.interval = nice(spanWithBreaks / splitNumber, true);
62	    if (minInterval != null && interval < minInterval) {
63	        interval = result.interval = minInterval;
64	    }
65	    if (maxInterval != null && interval > maxInterval) {
66	        interval = result.interval = maxInterval;
67	    }
68	    // Tow more digital for tick.
69	    const precision = result.intervalPrecision = getIntervalPrecision(interval);
70	    // Niced extent inside original extent
71	    const niceTickExtent = result.niceTickExtent = [
72	        round(Math.ceil(extent[0] / interval) * interval, precision),
73	        round(Math.floor(extent[1] / interval) * interval, precision)
74	    ];
75	
76	    fixExtent(niceTickExtent, extent);
77	
78	    return result;
79	}
80	
81	export function increaseInterval(interval: number) {
82	    const exponent = quantityExponent(interval);
83	    const exp10 = Math.pow(10, exponent);
84	    // Increase interval
85	    let f = interval / exp10;
86	    if (!f) {
87	        f = 1;
88	    }
89	    else if (f === 2) {
90	        f = 3;
91	    }
92	    else if (f === 3) {
93	        f = 5;
94	    }
95	    else { // f is 1 or 5
96	        f *= 2;
97	    }
98	    // The rounding precision has to follow the magnitude of the interval, otherwise
99	    // an extremely small interval (e.g. `1e-13`) would be rounded to `0`.
100	    return round(f * exp10, exponent < 0 ? -exponent : 0);
101	}
102	
103	/**
104	 * @return interval precision
105	 */
106	export function getIntervalPrecision(interval: number): number {
107	    // Tow more digital for tick.
108	    return getPrecision(interval) + 2;
109	}
110	
111	function clamp(
112	    niceTickExtent: [number, number], idx: number, extent: [number, number]
113	): void {
114	    niceTickExtent[idx] = Math.max(Math.min(niceTickExtent[idx], extent[1]), extent[0]);
115	}
116	
117	// In some cases (e.g., splitNumber is 1), niceTickExtent may be out of extent.
118	export function fixExtent(
119	    niceTickExtent: [number, number], extent: [number, number]
120	): void {
121	    !isFinite(niceTickExtent[0]) && (niceTickExtent[0] = extent[0]);
122	    !isFinite(niceTickExtent[1]) && (niceTickExtent[1] = extent[1]);
123	    clamp(niceTickExtent, 0, extent);
124	    clamp(niceTickExtent, 1, extent);
125	    if (niceTickExtent[0] > niceTickExtent[1]) {
126	        niceTickExtent[0] = niceTickExtent[1];
127	    }
128	}
129	
130	export function contain(val: number, extent: [number, number]): boolean {
131	    return val >= extent[0] && val <= extent[1];
132	}
133	
134	export class ScaleCalculator {
135	
136	    normalize: (val: number, extent: [number, number]) => number = normalize;
137	    scale: (val: number, extent: [number, number]) => number = scale;
138	
139	    updateMethods(brkCtx: ScaleBreakContext) {
140	        if (brkCtx.hasBreaks()) {
141	            this.normalize = bind(brkCtx.normalize, brkCtx);
142	            this.scale = bind(brkCtx.scale, brkCtx);
143	        }
144	        else {
145	            this.normalize = normalize;
146	            this.scale = scale;
147	        }
148	    }
149	}
150	
151	function normalize(
152	    val: number,
153	    extent: [number, number],
154	    // Dont use optional arguments for performance consideration here.
155	): number {
156	    if (extent[1] === extent[0]) {
157	        return 0.5;
158	    }
159	    return (val - extent[0]) / (extent[1] - extent[0]);
160	}
161	
162	function scale(
163	    val: number,
164	    extent: [number, number],
165	): number {
166	    return val * (extent[1] - extent[0]) + extent[0];
167	}
168	
169	export function logTransform(base: number, extent: number[], noClampNegative?: boolean): [number, number] {
170	    const loggedBase = Math.log(base);
171	    return [
172	        // log(negative) is NaN, so safe guard here.
173	        // PENDING: But even getting a -Infinity still does not make sense in extent.
174	        //  Just keep it as is, getting a NaN to make some previous cases works by coincidence.
175	        Math.log(noClampNegative ? extent[0] : Math.max(0, extent[0])) / loggedBase,
176	        Math.log(noClampNegative ? extent[1] : Math.max(0, extent[1])) / loggedBase
177	    ];
178	}

