/**
 * Round `val` by keeping the given count of significand digits, rather than by a
 * count of decimal places (which is what `round` does).
 *
 * `round` is based on `Number['prototype']['toFixed']`, therefore its precision
 * means "decimal places" and is capped at 20. It can not be used to erase the
 * floating point error of a value whose magnitude is unknown in advance - e.g.,
 * `round(1e-15)` returns `0` and the value is lost entirely. Use this method for
 * those cases (such as `Math.pow(base, exponent)` in log scale, where the
 * exponent can be a big negative number).
 *
 * @param significandDigits 1 to 21. `12` by default, which erases a similar
 *  amount of floating point error as `round` does for values around `1`.
 */
export function roundSignificand(val: number, significandDigits?: number): number {
    if (val === 0 || !isFinite(val)) {
        return val;
    }
    significandDigits = significandDigits == null
        ? SIGNIFICAND_DIGITS_DEFAULT
        // Avoid range error.
        : Math.min(Math.max(1, significandDigits), TO_PRECISION_SUPPORTED_MAX);
    return +val.toPrecision(significandDigits);
}

