143	    calcNiceTicks(approxTickNum: number): void {
144	        approxTickNum = approxTickNum || 10;
145	        const extent = this._extent.slice() as [number, number];
146	        const span = this._getExtentSpanWithBreaks();
147	        if (!isFinite(span) || span <= 0) {
148	            return;
149	        }
150	
151	        let interval = numberUtil.quantity(span);
152	        const err = approxTickNum / span * interval;
153	
154	        // Filter ticks to get closer to the desired count.
155	        if (err <= 0.5) {
156	            interval *= 10;
157	        }
158	
159	        // Interval should be integer
160	        while (!isNaN(interval) && Math.abs(interval) < 1 && Math.abs(interval) > 0) {
161	            interval *= 10;
162	        }
163	
164	        const niceExtent = [
165	            fixRound(mathCeil(extent[0] / interval) * interval),
166	            fixRound(mathFloor(extent[1] / interval) * interval)
167	        ] as [number, number];
